function cleanGoogle(text){const start=text.indexOf('{'),end=text.lastIndexOf('}');if(start<0||end<start)throw Error('Respons Google Sheets tidak valid');const result=JSON.parse(text.slice(start,end+1));if(result.status!=='ok'||!result.table)throw Error('Google Sheets belum dapat dibaca publik');const table=result.table;const raw=[table.cols.map(c=>c.label)];for(const row of table.rows){raw.push(table.cols.map((col,i)=>{const v=row.c[i]?.v;if(v==null)return '';if(col.type==='date'||col.type==='datetime'){const match=/^Date\((\d+),(\d+),(\d+)/.exec(v);if(!match)throw Error('Tanggal Google Sheets tidak valid');return new Date(Date.UTC(+match[1],+match[2],+match[3])).toISOString().slice(0,10)}return v}))}return cleanLive(raw)}
