function rebuildPicks(saved){$('filters').innerHTML=defs.map((d,i)=>{const opts=[...new Set(all.map(r=>d[1]===-1?r[0].slice(0,7):String(r[d[1]])))].sort(),keep=saved[i].filter(v=>opts.includes(v)),isAll=saved[i].includes('')||!keep.length;return '<label>'+d[0]+'<select id="f'+i+'" multiple aria-label="'+d[0]+'"><option value=""'+(isAll?' selected':'')+'>All — Semua</option>'+opts.map(v=>'<option value="'+esc(v)+'"'+(!isAll&&keep.includes(v)?' selected':'')+'>'+esc(d[1]===-1?month(v):v)+'</option>').join('')+'</select></label>'}).join('');setupPickers()}
