document.addEventListener('click',e=>{if(!e.target.closest('.filterwrap'))document.querySelectorAll('.filterpick').forEach(p=>p.open=false)});$('refresh').onclick=refreshLive;

function setupPickers(){defs.forEach((d,i)=>{const sel=$('f'+i),wrap=document.createElement('div');wrap.className='filterwrap';const old=sel.parentNode;old.parentNode.replaceChild(wrap,old);const label=document.createElement('label');label.textContent=String(i+1).padStart(2,'0')+' '+d[0];wrap.append(label,sel);const picker=document.createElement('details');picker.className='filterpick';picker.innerHTML='<summary aria-label="Pilih '+esc(d[0])+'">Semua '+esc(d[0])+'</summary><div class="pickpanel"><input type="search" placeholder="Cari '+esc(d[0].toLowerCase())+'…" aria-label="Cari '+esc(d[0])+'"><button type="button" class="pickclear">Pilih semua / hapus filter</button><div class="picklist"></div></div>';wrap.append(picker);const list=picker.querySelector('.picklist');[...sel.options].filter(o=>o.value!=='').forEach(o=>{let l=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=o.value;box.setAttribute('aria-label',o.text);box.addEventListener('change',()=>{sel.querySelector('option[value=""]').selected=false;[...sel.options].find(x=>x.value===box.value).selected=box.checked;if(!sel.selectedOptions.length)sel.options[0].selected=true;render()});l.append(box,document.createTextNode(o.text));list.append(l)});picker.querySelector('input[type=search]').addEventListener('input',e=>{[...list.children].forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});picker.querySelector('button').onclick=()=>{[...sel.options].forEach(o=>o.selected=o.value==='');render()};picker.addEventListener('toggle',()=>{if(picker.open)document.querySelectorAll('.filterpick').forEach(p=>{if(p!==picker)p.open=false})})});syncPickers()}
function syncPickers(){let chips=[];defs.forEach((d,i)=>{const sel=$('f'+i),wrap=sel.closest('.filterwrap');if(!wrap)return;const vals=chosen(i),isAll=vals.includes('');wrap.querySelector('summary').textContent=isAll?'Semua '+d[0]:vals.length===1?[...sel.selectedOptions][0].text:vals.length+' '+d[0]+' dipilih';wrap.querySelectorAll('.picklist input').forEach(b=>b.checked=!isAll&&vals.includes(b.value));if(!isAll)chips.push(d[0]+': '+(vals.length===1?[...sel.selectedOptions][0].text:vals.length+' pilihan'))});$('chips').innerHTML=chips.map(c=>'<span class="chip">'+esc(c)+'</span>').join('')}

const mixColors=['#087f72','#2f67a1','#a94c19','#7952a4','#9c3763','#596c21','#077e96','#8d5a31','#b33e40','#52647d','#b08c21','#477e47','#885f92','#575757'];
function composition(rows,index,valueIndex){const positive=rows.filter(r=>r[valueIndex]>0),names=[...new Set(positive.map(r=>r[index]||'Belum dipetakan'))].sort(),groups=new Map;for(const r of positive){if(!groups.has(r[2]))groups.set(r[2],{name:r[2],total:0,values:new Map});const g=groups.get(r[2]),name=r[index]||'Belum dipetakan';g.total+=r[valueIndex];g.values.set(name,(g.values.get(name)||0)+r[valueIndex])}return {names,groups:[...groups.values()].sort((a,b)=>b.total-a.total),negative:rows.some(r=>r[valueIndex]<0)}}
function chartPercent(value,total){const n=total?value/total*100:0;if(n>0&&n<0.01)return '<0,01%';return new Intl.NumberFormat('id-ID',{maximumFractionDigits:n<1?2:1}).format(n)+'%'}
function rankedSegments(group){return [...group.values.keys()].sort((a,b)=>group.values.get(b)-group.values.get(a)||a.localeCompare(b))}
function mixChart(index,label,target){const model=composition(filtered,index,metric),{names,groups}=model;if(!groups.length){$(target).innerHTML='<div class="empty">Tidak ada nilai penjualan positif untuk grafik '+label+'.</div>';return}const stable=[...new Set(all.map(r=>r[index]||'Belum dipetakan'))].sort(),color=name=>mixColors[stable.indexOf(name)%mixColors.length],metricName=$('metric').selectedOptions[0].text;
let html='<div class="mixlegend" aria-label="Legenda '+label+'">'+names.map(name=>'<span><i style="background:'+color(name)+'"></i>'+esc(name)+'</span>').join('')+'</div><p class="muted">Metrik: '+esc(metricName)+' · Segmen terbesar di bawah, terkecil di atas · Distributor diurutkan dari total nilai terbesar'+(model.negative?' · Grafik hanya memakai nilai positif; nilai negatif tetap termasuk ringkasan dan rincian.':'')+'.</p><div class="verticalchart"><div class="verticalaxis" aria-hidden="true"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="verticalscroll"><div class="verticalcolumns">';
html+=groups.map(g=>'<div class="mixrow"><div class="coltotal">'+short(g.total)+'</div><div class="mixbar" role="group" aria-label="Komposisi '+label+' '+esc(g.name)+'">'+rankedSegments(g).map(name=>{const value=g.values.get(name),p=value/g.total*100,description=g.name+' · '+name+': '+chartPercent(value,g.total)+' · '+money(value);return '<button type="button" class="mixsegment" style="height:'+p+'%;background:'+color(name)+'" aria-label="'+esc(description)+'" title="'+esc(description)+'" data-detail="'+esc(description)+'"><span class="mixpercent">'+(p>=12?'<span class="segmentname">'+esc(name)+'</span>':'')+(p>=5?esc(chartPercent(value,g.total)):'')+'</span></button>'}).join('')+'</div><div class="mixheading"><strong>'+esc(g.name.replace('DISTRIBUTOR ',''))+'</strong></div><div class="columnlabels" aria-label="Label lengkap '+label+' '+esc(g.name)+'">'+rankedSegments(g).map(name=>'<div class="columnlabel"><i style="background:'+color(name)+'"></i><span>'+esc(name)+'</span><b>'+esc(chartPercent(g.values.get(name),g.total))+'</b></div>').join('')+'</div></div>').join('');
html+='</div></div></div><p class="mixselection" role="status">Arahkan kursor atau klik segmen untuk melihat kategori, persentase, dan nominalnya.</p><p class="muted">Tiap kolom = 100% penjualan distributor setelah filter. Nama dan persentase semua kategori ditampilkan di bawah masing-masing kolom, termasuk segmen sangat kecil. Label di dalam segmen hanya ditampilkan jika ruangnya cukup. Geser grafik ke samping pada layar kecil. Pembulatan label dapat membuat jumlah tampak sedikit berbeda dari 100%.</p><details><summary>Lihat tabel persentase '+label+' lengkap</summary>'+table(['Distributor',metricName,...names],groups.map(g=>[g.name,money(g.total),...names.map(n=>pct(g.values.get(n)||0,g.total))]),Array.from({length:names.length+1},(_,i)=>i+1))+'</details>';const container=$(target);container.innerHTML=html;const show=e=>{const segment=e.target.closest('.mixsegment');if(segment)container.querySelector('.mixselection').textContent=segment.dataset.detail};container.onmouseover=show;container.onfocusin=show;container.onclick=show}
function renderMixCharts(){mixChart(11,'Type','typeMix');mixChart(10,'Series','seriesMix')}

init();
